// The unfinished onboardings and the most recent finished ones.
func (q *Queries) ListMetaOnboardings(ctx context.Context) ([]MetaOnboarding, error) {
	rows, err := q.db.Query(ctx, listMetaOnboardings)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MetaOnboarding{}
	for rows.Next() {
		var i MetaOnboarding
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.WabaID,
			&i.PhoneNumberID,
			&i.BusinessID,
			&i.Name,
			&i.Status,
			&i.Step,
			&i.BusinessTokenEnc,
			&i.PinEnc,
			&i.PinGenerated,
			&i.AccountID,
			&i.Attempts,
			&i.ErrorCode,
			&i.ErrorMessage,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.CompletedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

